const SUPA = 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1';
// n8n Code nodes cannot reach $credentials, so this key is inlined in the
// deployed workflow. The mirror carries a placeholder that sync.mjs resolves
// at deploy time (scripts/n8n/secrets.mjs) — the value never sits in git.
// Anon, not service role: every table read below carries an anon SELECT policy.
const KEY = '{{SUPABASE_ANON_KEY}}';
const hdr = { apikey: KEY, Authorization: `Bearer ${KEY}` };
const weekAgo = new Date(Date.now() - 7*86400000).toISOString();
// learning_events is read here and nowhere else in the system. Two routes
// write it (objectives, skill-proposal approval) and until now nothing ever
// read it, so the record of what the OS learned had no consumer. A weekly
// retro is the one surface where "what did we learn" is the actual question.
const monthAgo = new Date(Date.now() - 30*86400000).toISOString();
const [decidedBets, customers, completed, contacts, learning, stalls] = await Promise.all([
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/bets?status=in.(won,lost)&decided_at=gte.${weekAgo}&select=hypothesis,kind,status,learning,actual_mrr_impact_usd`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/customers?select=kind,mrr_usd,became_paid_at,churned_at,product`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/tasks?status=eq.done&completed_at=gte.${weekAgo}&select=title,agent,workstream`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/customer_contacts?contacted_at=gte.${weekAgo}&select=summary,reason`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/learning_events?created_at=gte.${monthAgo}&select=event_type,classification,pattern_text,recommended_change,status&limit=25`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/growth_stalls?status=eq.open&select=metric_key,baseline_value,latest_value,window_days`, headers: hdr, json: true }),
]);
const paidAdded = customers.filter(c => c.kind === 'paid' && c.became_paid_at >= weekAgo);
const churned   = customers.filter(c => c.kind === 'churned' && c.churned_at >= weekAgo);
const mrrDelta  = paidAdded.reduce((s,c)=>s+(Number(c.mrr_usd)||0),0) - churned.reduce((s,c)=>s+(Number(c.mrr_usd)||0),0);
return [{ json: { decidedBets, weekTasksDone: completed.length, contactCount: contacts.length, paidAdded: paidAdded.length, churned: churned.length, mrrDelta, sampleTasks: completed.slice(0,8), sampleContacts: contacts.slice(0,6), learningEvents: learning, openStalls: stalls } }];

parameters.jsonBody:
={{ JSON.stringify({ model: 'claude-sonnet-5', thinking: { type: 'adaptive' }, max_tokens: 6000, system: 'You are Marcus writing the Friday retro for Krish. You get this week's numbers and the learning events the OS recorded. Be brutal and specific.

Output ONLY a JSON object:
{"what_worked":string[], "what_flopped":string[], "next_focus":string}

what_worked and what_flopped: 2 to 4 each. Every entry is TWO clauses: what happened with its number, then what it means for next week. "Three Maven signups from the LinkedIn thread, so the channel is worth another week before judging it" not "LinkedIn did well". An entry with no number is not an entry. An entry that restates the number without saying what follows from it is a summary, and a summary is a failure.

next_focus: the ONE thing to drive next week, and it must name its first move. Format: the focus, then "Start by:" and a single concrete action doable Monday morning, naming the customer, lead, metric or bet it acts on. If an open stall or a recorded learning event points at the focus, say which.

Rules: cite real numbers from the data, never invent one. No platitudes, no "continue to", no "keep momentum". If the week was genuinely flat, say so plainly rather than manufacturing a win. No em dashes.', messages: [{ role: 'user', content: JSON.stringify($json) }] }) }}

