const blocks = $input.first().json.content || [];
const text = blocks.map(b=>b.text||'').join('').trim();
let retro = null;
try { const a=text.indexOf('{'); const b=text.lastIndexOf('}'); if (a>=0 && b>a) retro = JSON.parse(text.slice(a,b+1)); } catch {}
// Same rule as the daily brief: a retro that failed to parse must not render
// as a retro. It used to put the raw text into next_focus, so an unparseable
// week arrived on screen looking like Marcus's considered answer.
return [{ json: { retro: retro || { what_worked: [], what_flopped: [], next_focus: text, degraded: true, reasoning: 'fallback — the retro did not parse, shown raw' } } }];
